import { Plugin } from 'vue';

/**
 * Options of the PrimeVue plugin.
 */
export interface PrimeVueConfiguration {
    /**
     * Adds the ripple effect to buttons and other clickable components.
     *
     * @defaultValue false
     */
    ripple?: boolean;
    /**
     * The default look of form inputs. A component's own `variant` wins over it.
     *
     * @defaultValue null
     */
    inputVariant?: 'filled' | 'outlined' | undefined;
    /**
     * Texts and date settings the components use. Pass only the keys to change.
     */
    locale?: PrimeVueLocaleOptions;
    /**
     * The filter match modes offered for `text`, `numeric` and `date` columns.
     */
    filterMatchModeOptions?: any;
    /**
     * Base z-index of each overlay layer.
     */
    zIndex?: PrimeVueZIndexOptions;
    /**
     * The styled mode theme, such as `{ preset: Aura }`.
     *
     * @defaultValue undefined
     */
    theme?: any;
    /**
     * Renders components without the theme's styles, so they can be styled with custom CSS.
     *
     * @defaultValue false
     */
    unstyled?: boolean;
    /**
     * Resets the browser defaults on the native elements the components render, in the
     * `primeui.base` cascade layer so application styles override it without `!important`.
     * Leave it off when the application already resets these elements.
     *
     * @defaultValue false
     * @experimental
     */
    preflight?: boolean;
    /**
     * Pass through attributes for every component, keyed by component name.
     *
     * @defaultValue undefined
     */
    pt?: any;
    /**
     * How `pt` values merge with a component's own `pt`.
     *
     * @defaultValue { mergeSections: true, mergeProps: false }
     */
    ptOptions?: any;
    /**
     * Content Security Policy settings.
     */
    csp?: PrimeVueCSPOptions;
    /**
     * The license key.
     *
     * @defaultValue null
     */
    license?: string;
    /**
     * Gives the app its own theme, so it does not clash with other apps on the page.
     * Create it with `withIsolation` from `@primevue/core/isolation`.
     *
     * @example
     * app.use(PrimeVue, { theme, isolation: withIsolation({ key: 'shop' }) });
     *
     * @defaultValue undefined
     * @experimental
     */
    isolation?: PrimeVueIsolationOption;
    /**
     * Copies the page styles into the shadow roots the app renders in.
     * Create it with `withShadowRoot` from `@primevue/core/shadowroot`. Not needed with `isolation`.
     *
     * @example
     * app.use(PrimeVue, { theme, shadowRoot: withShadowRoot() });
     *
     * @defaultValue undefined
     * @experimental
     */
    shadowRoot?: PrimeVueShadowRootOption;
}

declare const shadowRootBrand: unique symbol;
declare const isolationBrand: unique symbol;

/**
 * The value `withShadowRoot` returns. Pass it to the `shadowRoot` option as is.
 */
export interface PrimeVueShadowRootOption {
    readonly [shadowRootBrand]: true;
}

/**
 * The value `withIsolation` returns. Pass it to the `isolation` option as is.
 */
export interface PrimeVueIsolationOption {
    readonly [isolationBrand]: true;
}

/**
 * The isolation of a running app, the same `Isolation` as in `@primeuix/styled/isolation`.
 * Read it with `useIsolation()`.
 *
 * @example
 * const isolation = useIsolation();
 * const release = isolation?.retain(myShadowRoot);
 *
 * @experimental
 */
export interface PrimeVueIsolation {
    /**
     * The app's key. Its root element and overlays carry it as `data-p-theme`.
     * Known once the app mounts.
     */
    readonly key: string;
    /**
     * The app's own theme.
     *
     * @example
     * getActionsInstance(isolation.theme).updatePreset(changes);
     */
    readonly theme: PrimeVueThemeRuntime;
    /**
     * Attributes that put an element inside the app's scope.
     *
     * @example
     * <div v-bind="isolation.attrs">
     */
    readonly attrs: Readonly<Record<'data-p-theme', string>>;
    /**
     * Limits CSS to the app's elements.
     *
     * @param css The CSS to scope.
     * @returns The scoped CSS.
     */
    scopeCSS(css: string): string;
    /**
     * Adds or replaces a style in every root the app renders in. The CSS is used as given, so pass it
     * through `scopeCSS` to limit it to the app.
     *
     * @param name A name unique within the app.
     * @param css The CSS text.
     * @param options Placement and nonce. The nonce defaults to `csp.nonce`.
     * @returns A function that removes the style.
     */
    set(name: string, css: string, options?: { first?: boolean; media?: string; nonce?: string }): () => void;
    /**
     * Removes a style added with `set`.
     *
     * @param name The style name.
     */
    delete(name: string): void;
    /**
     * Brings the app's styles into a shadow root or document it does not render in yet.
     *
     * @param target The root, or an element inside it.
     * @returns A function that releases the root.
     */
    retain(target: Document | ShadowRoot | Element | null | undefined): () => void;
    /**
     * Puts an element outside the app's tree, such as a popup appended to `body`, inside its scope
     * and dark mode.
     *
     * @param el The element.
     * @returns A function that takes the element out again.
     */
    hold(el: Element): () => void;
    /**
     * Applies the `set`, `delete` and `retain` calls inside `fn` together.
     *
     * @param fn The work to batch.
     * @returns What `fn` returns.
     */
    batch<T>(fn: () => T): T;
}

/**
 * The parts of `ThemeRuntime` from `@primeuix/styled` that an app uses.
 */
// Declared here because a CommonJS declaration file cannot import ESM-only types before TypeScript 5.3.
export interface PrimeVueThemeRuntime {
    /**
     * Returns the active theme configuration.
     */
    getTheme(): unknown;
    /**
     * Replaces the theme configuration, preset and options.
     */
    setTheme(theme: any): void;
    /**
     * Returns the active preset.
     */
    getPreset(): any;
    /**
     * Replaces the preset and keeps the options.
     */
    setPreset(preset: any): void;
    /**
     * Returns the active theme options.
     */
    getOptions(): any;
}

/**
 * The configuration PrimeVue starts from. Options passed to `app.use` are merged into it.
 */
export declare const defaultOptions: PrimeVueConfiguration;

/**
 * Base z-index of each overlay layer. Each open overlay gets a higher one.
 */
export interface PrimeVueZIndexOptions {
    /**
     * Base z-index of dialogs and other modal overlays.
     *
     * @defaultValue 1100
     */
    modal?: number;
    /**
     * Base z-index of dropdown panels and other overlays.
     *
     * @defaultValue 1000
     */
    overlay?: number;
    /**
     * Base z-index of menus.
     *
     * @defaultValue 1000
     */
    menu?: number;
    /**
     * Base z-index of tooltips.
     *
     * @defaultValue 1100
     */
    tooltip?: number;
}

/**
 * Content Security Policy settings.
 */
export interface PrimeVueCSPOptions {
    /**
     * Nonce added to every `<style>` element PrimeVue injects.
     *
     * @defaultValue undefined
     */
    nonce?: string;
}

