/**
 * Returns the PrimeVue configuration of the current app. Call it inside `setup`.
 *
 * @example
 * const { config } = usePrimeVue();
 * config.ripple = true;
 */
export declare function usePrimeVue(): {
    /**
     * The app's configuration. Changes apply to the app's components.
     */
    config: PrimeVueConfiguration;
};

/**
 * Returns the isolation of the current app, or `undefined` when it does not use isolated mode.
 * Call it inside `setup`.
 *
 * @example
 * const isolation = useIsolation();
 * let release;
 * onMounted(() => (release = isolation?.retain(shadowRoot)));
 * onUnmounted(() => release?.());
 *
 * @experimental
 */
export declare function useIsolation(): PrimeVueIsolation | undefined;

/**
 * The PrimeVue plugin.
 *
 * @example
 * app.use(PrimeVue, { theme: { preset: Aura } });
 */
declare const plugin: Plugin;
export default plugin;

declare module 'vue' {
    interface ComponentCustomProperties {
        /**
         * The PrimeVue configuration of the app.
         */
        $primevue: {
            /**
             * The app's configuration.
             */
            config: PrimeVueConfiguration;
        };
    }
}
